import{_ as t,o,c as s,ag as a}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"TypeScript & tooling","description":"","frontmatter":{},"headers":[],"relativePath":"kit/tooling.md","filePath":"kit/tooling.md"}'),i={name:"kit/tooling.md"};function n(d,e,r,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="typescript-tooling" tabindex="-1">TypeScript &amp; tooling <a class="header-anchor" href="#typescript-tooling" aria-label="Permalink to &quot;TypeScript &amp; tooling&quot;">​</a></h1><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p>fewui&#39;s source is JavaScript, but the package ships declarations generated from the components themselves (<code>types/index.d.ts</code>). You get:</p><ul><li><p><strong>Typed props in templates.</strong> Every <code>ui-*</code> tag is declared in Vue&#39;s <code>GlobalComponents</code>, so Volar completes props and flags unknown values:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!--        ^ Type &#39;&quot;error&quot;&#39; is not assignable to type &#39;&quot;primary&quot; | &quot;secondary&quot; | … --&gt;</span></span></code></pre></div></li><li><p><strong>Typed props in script</strong>: <code>import type { ButtonProps, DialogProps } from &#39;fewui&#39;</code>.</p></li><li><p><strong>Typed composables</strong>: <code>useToast</code>, <code>useConfirm</code>, <code>useDialog</code>, theme helpers (<code>setUiTheme</code>, <code>applyUiTheme</code>, <code>defineTheme</code>).</p></li></ul><p>Enum unions come from each prop&#39;s <code>validator</code>, so they cannot drift from the runtime. Less-used utilities are declared loosely (<code>any</code>) rather than guessed.</p><p>Nothing to configure: the <code>types</code> field and the <code>exports</code> map point at the declarations.</p><h2 id="machine-readable-component-data" tabindex="-1">Machine-readable component data <a class="header-anchor" href="#machine-readable-component-data" aria-label="Permalink to &quot;Machine-readable component data&quot;">​</a></h2><p><code>fewui/components.json</code> lists every component with its props (type, default, description), events and slots. It is the same data the docs are generated from, and is meant for editor tooling and AI agents:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> components </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fewui/components.json&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;json&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="working-on-fewui" tabindex="-1">Working on fewui <a class="header-anchor" href="#working-on-fewui" aria-label="Permalink to &quot;Working on fewui&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command (repo root)</th><th>What it does</th></tr></thead><tbody><tr><td><code>pnpm build:lib</code></td><td>Builds the library (<code>dist/</code>), after regenerating theme CSS, types and component docs</td></tr><tr><td><code>pnpm test</code></td><td>Unit and component tests (Vitest + happy-dom)</td></tr><tr><td><code>pnpm lint</code></td><td>ESLint — real errors only, no formatting rules</td></tr><tr><td><code>pnpm check</code></td><td>Everything CI runs: theme CSS, API vocabulary, generated files, types, lint, tests</td></tr><tr><td><code>pnpm build:meta</code></td><td>Regenerates <code>types/</code> and the component pages of this site</td></tr><tr><td><code>pnpm docs:dev</code></td><td>Playground on <code>:5175</code> (<code>?examples=1</code> lists every example)</td></tr><tr><td><code>pnpm kit-docs:dev</code></td><td>This site on <code>:5174</code></td></tr></tbody></table><h3 id="checks-that-run-before-every-build" tabindex="-1">Checks that run before every build <a class="header-anchor" href="#checks-that-run-before-every-build" aria-label="Permalink to &quot;Checks that run before every build&quot;">​</a></h3><ul><li><strong>Theme CSS</strong> — each <code>themes/&lt;id&gt;/color.css</code> is generated from <code>preset.js</code>; a stale file fails the check.</li><li><strong>API vocabulary</strong> — event names are kebab-case, <code>color</code> only takes tone names, <code>variant</code> never takes a tone, sizes come from the shared scale.</li><li><strong>Generated files</strong> — <code>types/</code> and the component pages must match the source.</li></ul><h3 id="adding-a-component" tabindex="-1">Adding a component <a class="header-anchor" href="#adding-a-component" aria-label="Permalink to &quot;Adding a component&quot;">​</a></h3><ol><li><code>packages/ui/src/components/&lt;Name&gt;.vue</code> — Options API, typed props with validators, explicit <code>emits</code>, text through <code>resolveUiText</code>.</li><li>Styles as <code>ui-&lt;name&gt;</code> classes in <code>themes/components/parts/&lt;name&gt;.css</code> (imported from <code>themes/components/index.css</code>).</li><li>Strings in <code>src/locales/tr.js</code> and <code>en.js</code>.</li><li>Register in <code>src/index.js</code> (import, named export, <code>GLOBAL_COMPONENTS</code>).</li><li>An example in <code>apps/docs/src/examples/&lt;Name&gt;Example.vue</code> — it becomes the live demo and the copy-paste snippet on the component page.</li><li>A test in <code>packages/ui/tests/components/</code>.</li><li><code>pnpm build:lib</code> — regenerates types and docs.</li></ol>`,15)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
